package pointer_labels
Row :: struct { pointer: ^int; labels: string[]; }
Main :: () -> int {
 number := 7;
 rows: Row[] = [{pointer: &number, labels: ["x"]}];
 pointer := &rows;
 selected := pointer.view(0..<1);
 if selected { row := selected[0]; return row.pointer^ + text_byte_length(row.labels[0]); }
 return -1;
}

package rootless_array_text
Row :: struct { labels: string[]; }
Literal :: () -> string { return "writer literal"; }
Rows :: () -> Row[] { return [{labels: [Literal()]}]; }
Owner :: () -> view Row[] { rows := Rows(); pointer := &rows; return pointer.view(0..<1)!; }
Write :: (window: view Row[]) { window[0] = {labels: [Literal()]}; }
Replace :: (pointer: ^(Row[])) -> ^(Row[]) { pointer^ = Rows(); return pointer; }
Main :: () -> int {
    window := Owner(); Write(window);
    rows := Rows(); pointer := &rows; Replace(pointer);
    return 0;
}

package rootless_inline_text
Leaf :: struct { label: string; }
Row :: struct { leaf: Leaf; }
Literal :: () -> string { return "writer literal"; }
Rows :: () -> Row[] { return [{leaf: {label: Literal()}}]; }
Owner :: () -> view Row[] { rows := Rows(); pointer := &rows; return pointer.view(0..<1)!; }
Write :: (window: view Row[]) { window[0] = {leaf: {label: Literal()}}; }
Replace :: (pointer: ^(Row[])) -> ^(Row[]) { pointer^ = Rows(); return pointer; }
Main :: () -> int {
    window := Owner(); Write(window);
    rows := Rows(); pointer := &rows; Replace(pointer);
    return 0;
}
